package com.github.tartaricacid.touhoulittlemaid.client.gui.entity.maid.ai.layout;

import com.github.tartaricacid.touhoulittlemaid.ai.service.tts.TTSSite;
import com.github.tartaricacid.touhoulittlemaid.ai.service.tts.siliconflow.TTSSiliconflowSite;
import com.github.tartaricacid.touhoulittlemaid.client.gui.entity.maid.ai.Translations;
import com.github.tartaricacid.touhoulittlemaid.client.gui.entity.maid.ai.layout.FieldDescriptor;
import com.github.tartaricacid.touhoulittlemaid.client.gui.entity.maid.ai.layout.TTSSiteFormLayout;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Function;
import net.minecraft.network.chat.Component;
import org.apache.commons.lang3.StringUtils;
import org.jetbrains.annotations.Nullable;

public class TTSSiliconflowFormLayout
extends TTSSiteFormLayout {
    public TTSSiliconflowFormLayout(TTSSite sourceSite) {
        super(sourceSite);
    }

    @Override
    public List<FieldDescriptor> getFieldDescriptors() {
        TTSSiliconflowSite site = (TTSSiliconflowSite)this.sourceSite;
        return List.of(new FieldDescriptor("url", site.url(), true, false), new FieldDescriptor("secret_key", site.secretKey(), true, true));
    }

    @Override
    public boolean supportsModelRows() {
        return true;
    }

    @Override
    public Map<String, String> getInitialModels() {
        return ((TTSSiliconflowSite)this.sourceSite).models();
    }

    @Override
    @Nullable
    public TTSSite buildSite(Function<String, String> fieldValues, Map<String, String> models, Consumer<Component> showStatus) {
        TTSSiliconflowSite site = (TTSSiliconflowSite)this.sourceSite;
        String url = fieldValues.apply("url");
        if (StringUtils.isBlank((CharSequence)url)) {
            showStatus.accept((Component)Translations.URL_IS_EMPTY);
            return null;
        }
        String secretKey = fieldValues.apply("secret_key");
        if (StringUtils.isBlank((CharSequence)secretKey)) {
            showStatus.accept((Component)Translations.SECRET_KEY_IS_EMPTY);
            return null;
        }
        if (models.isEmpty()) {
            showStatus.accept((Component)Translations.MODEL_IS_EMPTY);
            return null;
        }
        return new TTSSiliconflowSite(site.id(), site.icon(), url, site.enabled(), fieldValues.apply("secret_key"), site.headers(), models);
    }
}

